shellCommands.command:
node -e "
const fs=require('fs');
const p='lib/books.js';
let s=fs.readFileSync(p,'utf8');
const before=s;
s=s.replace(/\.replace\(\/\[[^\]]*\]\/g, ''\) \/\/ strip accents left by NFKD/, \".replace(/[\\\\u0300-\\\\u036f]/g, '') // strip accents left by NFKD\");
if(s===before) throw new Error('no match');
fs.writeFileSync(p,s);
" && grep -n "strip accents" lib/books.js

cat > jsconfig.json <<'EOF'
{
  "compilerOptions": {
    "paths": {
      "@/*": ["./*"]
    }
  }
}
EOF
cat > next.config.mjs <<'EOF'
/** @type {import('next').NextConfig} */
const nextConfig = {}

export default nextConfig
EOF
node -e "
const fs=require('fs');
const p=JSON.parse(fs.readFileSync('package.json','utf8'));
p.scripts={dev:'next dev',build:'next build',start:'next start',test:'vitest run'};
fs.writeFileSync('package.json', JSON.stringify(p,null,2)+'\n');
"
printf 'node_modules/\n__agent_eval__/\n.next/\ndata/books.json\n' > .gitignore
cat package.json .gitignore

ls .next/server/*.json | head; echo ---; node -e "
const m=require('./.next/server/server-reference-manifest.json');
console.log(Object.keys(m));
const ids=Object.keys(m.node||{});
for(const id of ids) console.log(id, JSON.stringify(m.node[id].workers||{}).slice(0,80));
" 2>&1 | head -20

echo "=== /books/dune ==="; curl -s -w '
status:%{http_code}
' localhost:3111/books/dune -o /tmp/b.html; grep -oE '<title>[^<]*|<h1[^>]*>[^<]*|class="book-author">[^<]*|The spice must flow\.|badge-finished|Move back to reading' /tmp/b.html | sort -u
echo; echo "=== /books/piranesi (reading) ==="; curl -s localhost:3111/books/piranesi | grep -oE 'Mark as finished|class="badge">[^<]*|Susanna Clarke|since [0-9]+ [A-Za-z]+ [0-9]+' | sort -u
echo; echo "=== /books/does-not-exist ==="; curl -s -o /tmp/nf.html -w 'status:%{http_code}
' localhost:3111/books/does-not-exist; grep -oE 'Book not found|doesn.{1,8}t point at a book' /tmp/nf.html | sort -u

cat > vitest.config.mjs <<'EOF'
import path from 'node:path'
import { defineConfig } from 'vitest/config'

export default defineConfig({
  resolve: {
    alias: { '@': path.resolve(import.meta.dirname) },
  },
})
EOF
npm test 2>&1 | tail -12
